Solution B: function initGameOfLife(canvasId){const canvas=document.getElementById(canvasId);if(!canvas||!canvas.getContext)return;canvas.width=500;canvas.height=500;const ctx=canvas.getContext('2d');const cellSize=20;const rows=Math.floor(canvas.height/cellSize);const cols=Math.floor(canvas.width/cellSize);let grid=Array.from({length:rows},()=>Array(cols).fill(0));let age=Array.from({length:rows},()=>Array(cols).fill(0));let fade=Array.from({length:rows},()=>Array(cols).fill(0));const emojis=['🟦','🟩','🟨','🟧','🟥'];let speed=5;let lastTick=0;let running=true;function createEmpty(){return Array.from({length:rows},()=>Array(cols).fill(0));}function step(){let next=createEmpty();let nextAge=createEmpty();for(let y=0;y<rows;y++){for(let x=0;x<cols;x++){let neighbors=0;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)if(!(dx===0&&dy===0)){let ny=(y+dy+rows)%rows;let nx=(x+dx+cols)%cols;if(grid[ny][nx])neighbors++;}if(grid[y][x]){if(neighbors===2||neighbors===3){next[y][x]=1;nextAge[y][x]=age[y][x]+1;fade[y][x]=0;}else{fade[y][x]=1;}}else{if(neighbors===3){next[y][x]=1;nextAge[y][x]=1;fade[y][x]=0;}}}}grid=next;age=nextAge;}function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=cellSize*0.9+'px sans-serif';for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){if(grid[y][x]){let a=Math.min(age[y][x],emojis.length)-1;ctx.globalAlpha=1;ctx.fillText(emojis[a],x*cellSize+cellSize/2,y*cellSize+cellSize/2);}else if(fade[y][x]>0){ctx.globalAlpha=fade[y][x];ctx.fillText('⚫',x*cellSize+cellSize/2,y*cellSize+cellSize/2);fade[y][x]-=0.05;if(fade[y][x]<=0)fade[y][x]=0;}}ctx.globalAlpha=1;}function loop(ts){if(running){if(ts-lastTick>1000/speed){step();lastTick=ts;}draw();requestAnimationFrame(loop);}}function toggleCell(e){const rect=canvas.getBoundingClientRect();const x=Math.floor((e.clientX-rect.left)/cellSize);const y=Math.floor((e.clientY-rect.top)/cellSize);if(x>=0&&x<cols&&y>=0&&y<rows){grid[y][x]=grid[y][x]?0:1;age[y][x